<script setup lang="ts">
import { canTransitionAppointment } from "~/utils/appointmentTransitions"
definePageMeta({layout:false})
const auth=useCounselorAuth(),tab=ref('appointments'),busy=ref(false),error=ref(''),success=ref('')
const appointments=ref<any[]>([]),finance=ref<any>(null),availability=ref<any>(null),notifications=ref<any[]>([]),active=ref<any>(null),notes=ref<any[]>([]),editingNote=ref<any>(null),noteVersions=ref<any[]>([]),versionDialog=ref(false),selectedVersion=ref<any>(null)
const noteDraft=reactive({body:'',follow_up_recommendations:'',treatment_progress:'',status:'draft'}),clientRecord=ref<any>(null),clientAnswers=ref<any[]>([]),clientConsents=ref<any[]>([]),clientFollowUps=ref<any[]>([]),clientAttachments=ref<any[]>([]),activeClient=ref<any>(null),clinicalBusy=ref(false),clinicalFile=ref<File|null>(null)
const followUp=reactive({title:'',details:'',due_date:''}),timeOff=reactive({starts_at:'',ends_at:'',reason:''}),tabs=[{key:'appointments',title:'نوبت‌های من'},{key:'clients',title:'مراجعان من'},{key:'availability',title:'برنامه و مرخصی'},{key:'finance',title:'درآمد و تسویه'},{key:'notifications',title:'اعلان‌ها'}]
useHead({title:'پنل مشاور | مرکز مشاوره',htmlAttrs:{lang:'fa'}})
const money=(n:number)=>`${Number(n||0).toLocaleString('fa-IR')} ریال`
const dateTime=(s:string)=>s?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',dateStyle:'medium',timeStyle:'short'}).format(new Date(s.endsWith('Z')||/[+-]\d\d:\d\d$/.test(s)?s:`${s.replace(' ','T')}Z`)):'—'
const errorText=(e:any)=>e?.status===403?'دسترسی مجاز نیست.':e?.status===404?'این نوبت در دسترس نیست.':e?.status===409?'این عملیات با زمان‌بندی فعلی تداخل دارد.':e?.data?.message||Object.values(e?.data?.errors||{}).flat().join(' ')||'درخواست انجام نشد.'
async function load(){busy.value=true;error.value='';try{const [a,f,v,n]=await Promise.all([auth.request<any>('/counselor/appointments'),auth.request<any>('/counselor/finances'),auth.request<any>('/counselor/availability'),auth.request<any>('/counselor/notifications')]);appointments.value=a.data?.data||a.data||[];finance.value=f.data;availability.value=v.data;notifications.value=n.data?.data||n.data||[]}catch(e){error.value=errorText(e)}finally{busy.value=false}}
const assignedClients=computed(()=>Array.from(new Map(appointments.value.map(row=>[row.user_id,{id:row.user_id,name:row.client_name,phone:row.client_phone}])).values()))
async function openAppointment(row:any){active.value=row;notes.value=[];editingNote.value=null;error.value='';try{notes.value=(await auth.request<any>(`/counselor/appointments/${row.id}/notes`)).data||[];const draft=notes.value.find((note:any)=>note.status==='draft');if(draft)editNote(draft);else Object.assign(noteDraft,{body:'',follow_up_recommendations:'',treatment_progress:'',status:'draft'})}catch(e){error.value=errorText(e)}}
function editNote(note:any){if(note.status!=='draft')return;editingNote.value=note;Object.assign(noteDraft,{body:note.body||'',follow_up_recommendations:note.follow_up_recommendations||'',treatment_progress:note.treatment_progress||'',status:'draft'})}
async function openNoteVersions(note:any){try{const r:any=await auth.request(`/counselor/session-notes/${note.id}/versions`);noteVersions.value=r.data?.data||r.data||[];selectedVersion.value=null;versionDialog.value=true}catch(e){error.value=errorText(e)}}
async function showNoteVersion(note:any,version:any){try{const r:any=await auth.request(`/counselor/session-notes/${note.id}/versions/${version.version}`);selectedVersion.value=r.data||null}catch(e){error.value=errorText(e)}}
async function perform(action:()=>Promise<void>){busy.value=true;error.value='';success.value='';try{await action();if(!success.value)success.value='تغییر ثبت شد.'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function saveNote(finalize=false){if(!active.value||!noteDraft.body.trim())return;const status=finalize?'finalized':'draft';if(finalize&&!confirm('یادداشت نهایی شود؟ پس از نهایی‌سازی قابل ویرایش نخواهد بود.'))return;await perform(async()=>{const body={...noteDraft,status,body:noteDraft.body.trim()};if(editingNote.value)await auth.request(`/counselor/session-notes/${editingNote.value.id}`,{method:'PATCH',body});else{const result:any=await auth.request(`/counselor/appointments/${active.value.id}/notes`,{method:'POST',body});editingNote.value=result.data}await openAppointment(active.value);success.value=status==='finalized'?'یادداشت نهایی و قفل شد.':'پیش‌نویس ذخیره شد.'})}
async function setStatus(status:'in_progress'|'completed'|'no_show'){if(!active.value)return;const allowed=canTransitionAppointment(active.value.status,status);if(!allowed)return;await perform(async()=>{await auth.request(`/counselor/appointments/${active.value.id}/status`,{method:'PATCH',body:{status}});active.value.status=status;await load()})}
async function updateConnection(){if(!active.value)return;await perform(async()=>{await auth.request(`/counselor/appointments/${active.value.id}/session-details`,{method:'PATCH',body:{session_mode:active.value.session_mode||'meet',connection:active.value.session_connection||'',instructions:active.value.session_instructions||''}});success.value='اطلاعات اتصال ثبت شد.';await load()})}
async function requestTimeOff(){const offset=(s:string)=>`${s}:00+03:30`;await perform(async()=>{await auth.request('/counselor/time-off',{method:'POST',body:{starts_at:offset(timeOff.starts_at),ends_at:offset(timeOff.ends_at),reason:timeOff.reason}});Object.assign(timeOff,{starts_at:'',ends_at:'',reason:''});await load()})}
async function openClient(client:any){activeClient.value=client;clinicalBusy.value=true;error.value='';try{const [r,a,c,f,d]=await Promise.all([auth.request<any>(`/counselor/clients/${client.id}/clinical-record`),auth.request<any>(`/counselor/clients/${client.id}/intake-answers`),auth.request<any>(`/counselor/clients/${client.id}/consents`),auth.request<any>(`/counselor/clients/${client.id}/follow-ups`),auth.request<any>(`/counselor/clients/${client.id}/attachments`)]);clientRecord.value=r.data||{};clientAnswers.value=a.data?.data||a.data||[];clientConsents.value=c.data||[];clientFollowUps.value=f.data?.data||f.data||[];clientAttachments.value=d.data?.data||d.data||[]}catch(e){error.value=errorText(e)}finally{clinicalBusy.value=false}}
async function saveClientRecord(){if(!activeClient.value)return;clinicalBusy.value=true;error.value='';try{const r:any=await auth.request(`/counselor/clients/${activeClient.value.id}/clinical-record`,{method:'PUT',body:clientRecord.value});clientRecord.value=r.data;success.value='پرونده ذخیره شد.'}catch(e){error.value=errorText(e)}finally{clinicalBusy.value=false}}
async function addFollowUp(){if(!activeClient.value||!followUp.title.trim())return;clinicalBusy.value=true;try{await auth.request(`/counselor/clients/${activeClient.value.id}/follow-ups`,{method:'POST',body:{...followUp}});Object.assign(followUp,{title:'',details:'',due_date:''});await openClient(activeClient.value);success.value='پیگیری ثبت شد.'}catch(e){error.value=errorText(e)}finally{clinicalBusy.value=false}}
async function completeFollowUp(task:any){clinicalBusy.value=true;try{await auth.request(`/counselor/follow-ups/${task.id}/complete`,{method:'POST'});await openClient(activeClient.value);success.value='پیگیری تکمیل شد.'}catch(e){error.value=errorText(e)}finally{clinicalBusy.value=false}}
async function uploadClinicalFile(){if(!activeClient.value||!clinicalFile.value)return;clinicalBusy.value=true;try{const body=new FormData();body.append('file',clinicalFile.value);await auth.request(`/counselor/clients/${activeClient.value.id}/attachments`,{method:'POST',body});clinicalFile.value=null;await openClient(activeClient.value);success.value='فایل خصوصی بارگذاری شد.'}catch(e){error.value=errorText(e)}finally{clinicalBusy.value=false}}
async function downloadClinicalFile(item:any){try{const config=useRuntimeConfig(),response=await fetch(`${config.public.apiBase}/counselor/clinical/attachments/${item.id}`,{headers:{Authorization:`Bearer ${auth.token.value}`}});if(!response.ok)throw {status:response.status,data:{message:'دانلود فایل مجاز نیست یا انجام نشد.'}};const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download=item.original_name;anchor.click();URL.revokeObjectURL(url)}catch(e){error.value=errorText(e)}}
async function readNotification(item:any){if(item.read_at)return;try{await auth.request(`/counselor/notifications/${item.id}/read`,{method:'POST'});item.read_at=new Date().toISOString()}catch(e){error.value=errorText(e)}}
async function logout(){try{await auth.request('/counselor/logout',{method:'POST'})}catch{}auth.clear();await navigateTo('/counselor/login',{replace:true})}
onMounted(load)
</script>
<template><main class="counselor-portal" dir="rtl">
<header class="counselor-portal__header"><div><p>فضای کاری مشاور</p><h1>نوبت‌ها و جلسات</h1></div><div class="d-flex ga-2"><v-btn variant="tonal" :loading="busy" @click="load">تازه‌سازی</v-btn><v-btn variant="outlined" @click="logout">خروج</v-btn></div></header>
<v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-4">{{success}}</v-alert>
<v-tabs v-model="tab" color="primary" class="mb-5"><v-tab v-for="item in tabs" :key="item.key" :value="item.key">{{item.title}}</v-tab></v-tabs>
<section v-if="tab==='appointments'"><v-progress-linear v-if="busy" indeterminate class="mb-3"/><v-card v-for="row in appointments" :key="row.id" class="counselor-appointment mb-3" @click="openAppointment(row)"><div class="d-flex flex-wrap justify-space-between ga-2"><div><strong>نوبت #{{row.id}} · {{row.client_name}}</strong><p>{{row.service_name}} · {{dateTime(row.starts_at)}}</p></div><v-chip>{{row.status}}</v-chip></div><p class="mb-0">{{row.session_mode==='meet'?'Google Meet':row.session_mode==='voice_call'?'تماس تلفنی':'حضوری'}} · {{row.session_instructions||'راهنمای جلسه ثبت نشده است.'}}</p><div v-if="row.connection_available&&row.session_mode==='meet'&&row.session_connection"><a :href="row.session_connection" target="_blank" rel="noopener noreferrer" @click.stop>ورود به جلسه</a></div></v-card><v-alert v-if="!busy&&!appointments.length" type="info" variant="tonal">نوبتی برای نمایش نیست.</v-alert>
<v-card v-if="active" class="pa-5 mt-5" id="counselor-appointment-detail"><div class="d-flex justify-space-between align-center"><h2>نوبت #{{active.id}} · {{active.client_name}}</h2><v-btn icon="mdi-close" variant="text" aria-label="بستن جزئیات" @click="active=null"/></div><p>{{active.service_name}} · {{dateTime(active.starts_at)}} · {{active.status}}</p><p v-if="active.session_instructions">{{active.session_instructions}}</p><a v-if="active.connection_available&&active.session_mode==='meet'&&active.session_connection" :href="active.session_connection" target="_blank" rel="noopener noreferrer">بازکردن Google Meet</a><a v-if="active.connection_available&&active.session_mode==='voice_call'&&active.session_connection" :href="`tel:${active.session_connection}`">{{active.session_connection}}</a>
<v-divider class="my-4"/><div class="d-flex justify-space-between align-center"><h3>یادداشت محرمانهٔ جلسه</h3><v-btn v-if="editingNote" size="small" variant="text" @click="editingNote=null;Object.assign(noteDraft,{body:'',follow_up_recommendations:'',treatment_progress:'',status:'draft'})">پیش‌نویس تازه</v-btn></div><v-list><v-list-item v-for="note in notes" :key="note.id" :title="`یادداشت ${note.status==='finalized'?'نهایی':'پیش‌نویس'} · ${dateTime(note.updated_at||note.created_at)}`" :subtitle="note.body"><template #append><v-btn v-if="note.status==='draft'" size="small" @click="editNote(note)">ویرایش پیش‌نویس</v-btn><template v-else><v-chip color="success" class="ml-2">نهایی و قفل‌شده</v-chip><v-btn size="small" variant="text" @click="openNoteVersions(note)">تاریخچه نسخه</v-btn></template></template></v-list-item><v-list-item v-if="!notes.length" title="یادداشتی ثبت نشده است."/></v-list><v-textarea v-model="noteDraft.body" label="متن یادداشت خصوصی" rows="4"/><v-textarea v-model="noteDraft.treatment_progress" label="پیشرفت درمان" rows="2"/><v-textarea v-model="noteDraft.follow_up_recommendations" label="پیشنهاد پیگیری" rows="2"/><div class="d-flex ga-2"><v-btn :disabled="busy||!noteDraft.body.trim()" @click="saveNote(false)">ذخیرهٔ پیش‌نویس</v-btn><v-btn color="primary" :disabled="busy||!noteDraft.body.trim()" @click="saveNote(true)">نهایی‌سازی و قفل</v-btn></div>
<v-divider class="my-4"/><h3>اطلاعات اتصال جلسه</h3><v-select v-model="active.session_mode" label="روش جلسه" :items="[{title:'حضوری',value:'in_person'},{title:'پیوند Google Meet',value:'meet'},{title:'تماس تلفنی',value:'voice_call'}]"/><v-text-field v-if="active.session_mode!=='in_person'" v-model="active.session_connection" :label="active.session_mode==='meet'?'پیوند Meet':'شماره تماس'"/><v-textarea v-model="active.session_instructions" label="راهنمای جلسه (اختیاری)" rows="2"/><v-btn :disabled="busy" @click="updateConnection">ذخیره اطلاعات جلسه</v-btn><div class="d-flex flex-wrap ga-2 mt-4"><v-btn v-if="active.status==='checked_in'" color="primary" :disabled="busy" @click="setStatus('in_progress')">شروع جلسه</v-btn><v-btn v-if="['confirmed','checked_in','in_progress'].includes(active.status)" color="success" :disabled="busy" @click="setStatus('completed')">ثبت برگزاری</v-btn><v-btn v-if="active.status==='confirmed'" color="error" variant="outlined" :disabled="busy" @click="setStatus('no_show')">ثبت عدم حضور</v-btn></div></v-card></section>
<section v-else-if="tab==='clients'"><v-card class="pa-4 mb-4"><h2>مراجعان دارای نوبت با شما</h2><v-list><v-list-item v-for="client in assignedClients" :key="client.id" :title="client.name" :subtitle="client.phone||''"><template #append><v-btn size="small" @click="openClient(client)">پروندهٔ مجاز</v-btn></template></v-list-item><v-list-item v-if="!assignedClients.length" title="مراجعی در نوبت‌های این صفحه پیدا نشد."/></v-list></v-card><v-progress-linear v-if="clinicalBusy" indeterminate/><template v-if="activeClient"><v-card class="pa-5 mb-4"><h2>پروندهٔ بالینی · {{activeClient.name}}</h2><v-textarea v-model="clientRecord.client_concerns" label="نگرانی‌های مطرح‌شده"/><v-combobox v-model="clientRecord.treatment_goals" label="هدف‌های درمانی" multiple chips/><v-textarea v-model="clientRecord.progress_summary" label="خلاصهٔ پیشرفت"/><v-btn :disabled="clinicalBusy" @click="saveClientRecord">ذخیرهٔ پرونده</v-btn></v-card><v-row><v-col cols="12" lg="6"><v-card class="pa-4"><h3>پاسخ‌های فرم نسخه‌دار</h3><v-list><v-list-item v-for="answer in clientAnswers" :key="answer.id" :title="`${answer.form_title} · نسخه ${answer.version}`" :subtitle="`${dateTime(answer.submitted_at)} · ${answer.answers}`"/><v-list-item v-if="!clientAnswers.length" title="پاسخی ثبت نشده است."/></v-list></v-card></v-col><v-col cols="12" lg="6"><v-card class="pa-4"><h3>رضایت‌ها</h3><v-list><v-list-item v-for="consent in clientConsents" :key="consent.id" :title="`${consent.consent_key} · نسخه ${consent.version}`" :subtitle="dateTime(consent.accepted_at)"/><v-list-item v-if="!clientConsents.length" title="رضایتی ثبت نشده است."/></v-list></v-card></v-col></v-row><v-card class="pa-4 my-4"><h3>پیگیری‌های بعدی</h3><v-text-field v-model="followUp.title" label="عنوان"/><v-text-field v-model="followUp.due_date" type="date" label="سررسید"/><v-textarea v-model="followUp.details" label="جزئیات"/><v-btn :disabled="clinicalBusy||!followUp.title.trim()" @click="addFollowUp">ثبت پیگیری</v-btn><v-list><v-list-item v-for="task in clientFollowUps" :key="task.id" :title="task.title" :subtitle="`${task.due_date||'بدون سررسید'} · ${task.details||''}`"><template #append><v-btn v-if="!task.completed_at" size="small" :disabled="clinicalBusy" @click="completeFollowUp(task)">تکمیل</v-btn></template></v-list-item><v-list-item v-if="!clientFollowUps.length" title="پیگیری‌ای ثبت نشده است."/></v-list></v-card><v-card class="pa-4"><h3>فایل‌های خصوصی</h3><v-file-input v-model="clinicalFile" label="انتخاب فایل خصوصی" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"/><v-btn :disabled="clinicalBusy||!clinicalFile" @click="uploadClinicalFile">بارگذاری امن</v-btn><v-list><v-list-item v-for="item in clientAttachments" :key="item.id" :title="item.original_name" :subtitle="`${item.mime_type} · ${Number(item.size_bytes).toLocaleString('fa-IR')} بایت`"><template #append><v-btn size="small" @click="downloadClinicalFile(item)">دانلود امن</v-btn></template></v-list-item><v-list-item v-if="!clientAttachments.length" title="فایلی بارگذاری نشده است."/></v-list></v-card></template><v-alert v-else type="info" variant="tonal">برای دسترسی بالینی، یکی از مراجعان دارای رزرو با حساب مشاور خود را انتخاب کنید.</v-alert></section><section v-else-if="tab==='availability'"><v-row><v-col cols="12" md="6"><v-card class="pa-4"><h2>ساعات کاری</h2><v-list><v-list-item v-for="shift in availability?.shifts||[]" :key="shift.id" :title="`${['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'][shift.weekday]} · ${shift.starts_at.slice(0,5)} تا ${shift.ends_at.slice(0,5)}`" :subtitle="shift.is_active?'فعال':'غیرفعال'"/></v-list></v-card></v-col><v-col cols="12" md="6"><v-card class="pa-4"><h2>ثبت درخواست مرخصی</h2><v-text-field v-model="timeOff.starts_at" type="datetime-local" label="شروع (تهران)"/><v-text-field v-model="timeOff.ends_at" type="datetime-local" label="پایان (تهران)"/><v-text-field v-model="timeOff.reason" label="توضیح"/><v-btn :disabled="busy||!timeOff.starts_at||!timeOff.ends_at" @click="requestTimeOff">ثبت درخواست</v-btn><v-list><v-list-item v-for="off in availability?.time_off?.data||[]" :key="off.id" :title="`${dateTime(off.starts_at)} تا ${dateTime(off.ends_at)}`" :subtitle="off.reason"/></v-list></v-card></v-col></v-row></section>
<section v-else-if="tab==='finance'"><v-row v-if="finance"><v-col v-for="m in [{key:'earned_irr',title:'سهم ثبت‌شده'},{key:'reversed_irr',title:'برگشت سهم'},{key:'settled_irr',title:'تسویه‌شده'},{key:'payable_irr',title:'مانده قابل پرداخت'}]" :key="m.key" cols="12" sm="6" lg="3"><v-card class="pa-5"><p>{{m.title}}</p><strong>{{money(finance[m.key])}}</strong></v-card></v-col></v-row><v-card class="pa-4"><h2>سوابق تسویه</h2><v-table><thead><tr><th>مبلغ</th><th>مرجع</th><th>تاریخ</th></tr></thead><tbody><tr v-for="item in finance?.settlements?.data||[]" :key="item.id"><td>{{money(item.amount_irr)}}</td><td>{{item.reference}}</td><td>{{dateTime(item.created_at)}}</td></tr></tbody></v-table></v-card></section>
<section v-else><v-card><v-list><v-list-item v-for="item in notifications" :key="item.id" :title="item.title||item.event||'اعلان جلسه'" :subtitle="item.body||item.status"/></v-list><v-alert v-if="!notifications.length" type="info" variant="tonal">اعلانی موجود نیست.</v-alert></v-card></section>
</main><v-dialog v-model="versionDialog" max-width="900" scrollable><v-card class="pa-5" dir="rtl"><h2>تاریخچه نسخه یادداشت</h2><v-row><v-col cols="12" md="4"><v-list><v-list-item v-for="version in noteVersions" :key="version.id" :title="`نسخه ${version.version} · ${dateTime(version.created_at)}`" :subtitle="version.author_name" @click="showNoteVersion(notes.find((n:any)=>n.id===version.note_id),version)"/></v-list></v-col><v-col cols="12" md="8"><template v-if="selectedVersion"><v-alert type="info" variant="tonal">نویسنده: {{selectedVersion.author_name}} · فیلدهای تغییرکرده: {{selectedVersion.changed_fields?.join('، ')||'—'}}</v-alert><pre class="note-snapshot">{{JSON.stringify(selectedVersion.snapshot,null,2)}}</pre></template><div v-else class="text-medium-emphasis pa-4">برای مشاهده نسخه انتخاب کنید.</div></v-col></v-row><v-card-actions><v-spacer/><v-btn @click="versionDialog=false">بستن</v-btn></v-card-actions></v-card></v-dialog></template>
<style scoped>.counselor-portal{max-width:1200px;margin:0 auto;padding:28px 18px}.counselor-portal__header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.counselor-portal__header p{margin:0;color:#577067}.counselor-portal__header h1{margin:4px 0}.counselor-appointment{padding:18px 20px;cursor:pointer;border:1px solid #e5e8e4}.counselor-appointment p{margin:8px 0;color:#606b66}.counselor-portal strong{font-size:1.1rem}@media(max-width:600px){.counselor-portal__header{align-items:flex-start;flex-direction:column}.counselor-portal{padding:18px 12px}}</style>
